def _parse_attrs(options: Dict[str, Any]) ->Dict[str, Any]:
    attrs = {}

    if 'alt' in options:
        attrs['alt'] = options['alt']

    if 'width' in options:
        attrs['width'] = options['width']

    if 'height' in options:
        attrs['height'] = options['height']

    if 'align' in options:
        align = options['align']
        if align in _allowed_aligns:
            attrs['align'] = align

    if 'target' in options:
        attrs['target'] = options['target']

    return attrs
